        ["[0.0, 2.0] [0.5, -1.0]", "[0.0, 2.0] [0.0, 2.0]", "[2.0, 0.0] [0.5, -1.0]", "[1.0, 2.0] [0.5, -1.0]"], 0,
        "Inference reads the weights; it does not change them.",
